(async () => { const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const c=[]; const push=(k,pass,detail)=>c.push({k,pass:!!pass,detail:(detail==null?'':String(detail)).slice(0,100)}); for(let i=0;i<90 && !document.getElementById('spbEasyRail');i++) await sleep(400); await sleep(3000);
// [SPB-OVERNIGHT V2-LADDER 2026-08-22] Featured Collections contract
const hdrs=[...document.querySelectorAll('.spb-easy-finish-group')];
const colls=hdrs.filter(g=>g.textContent.indexOf('PICKS')>-1);
push('3 featured collection shelves render', colls.length===3, hdrs.map(g=>g.textContent.trim().slice(0,22)).join('|').slice(0,100));
const starterIdx=hdrs.findIndex(g=>g.textContent.indexOf('STARTER SHELF')>-1); const firstColl=hdrs.findIndex(g=>g.textContent.indexOf('PICKS')>-1);
push('collections lead the generic starter shelf', firstColl>-1 && starterIdx>firstColl, firstColl+' vs '+starterIdx);
const seeAll=colls[0]?colls[0].querySelector('[data-tag]'):null; push('SEE ALL button carries data-tag', !!seeAll);
if(seeAll){ const t=seeAll.getAttribute('data-tag'); seeAll.click(); await sleep(900); const flat=[...document.querySelectorAll('.spb-easy-finish-group')].some(g=>/MATCH/i.test(g.textContent)); push('SEE ALL applies its filter', flat, 'tag='+t); }
return JSON.stringify(c); })()
